function withTimeout<T>(promise: Promise<T>, ms: number, label: string): Promise<T> {
  return Promise.race([
    promise,
    new Promise<never>((_, reject) =>
      setTimeout(() => reject(new Error(`${label} timed out after ${ms}ms`)), ms),
    ),
  ]);
}

new Bot<TContext>(token, {
  client: proxyUrl
    ? { baseFetchConfig: { agent: new SocksProxyAgent(proxyUrl), compress: true } }
    : undefined,
});

function emptyAsUndefined<T extends z.ZodType>(schema: T) {
  return z.preprocess((val) => {
    if (typeof val === "string" && val.trim() === "") return undefined;
    return val;
  }, schema);
}

const found = await tx.telegramUser.findUnique({
  where: { chatId: BigInt(chatId) },
  select: { id: true, chatId: true },
});
const user = found ?? (await tx.telegramUser.create({
  data: { chatId: BigInt(chatId), isActive: true },
  select: { id: true, chatId: true },
}));

const user = await prisma.telegramUser.findUnique({
  where: { chatId: userId, isActive: true },        // account gate (parent)
  select: {
    userRoles: {
      where: { revokedAt: null },                   // role gate (children)
      select: { role: { select: { rolePermissions: {
        select: { permission: { select: { name: true } } },
      } } } },
    },
  },
});
if (!user) return new Set();
return new Set(user.userRoles.flatMap((ur) =>
  ur.role.rolePermissions.map((rp) => rp.permission.name)));

const { count } = await prisma.userRole.updateMany({
  where: {
    userId: user.id,
    role: { name: Roles.MANAGER },
    revokedAt: null, // guard: don't overwrite an existing revocation timestamp
  },
  data: { revokedAt: new Date() },
});
return count > 0 ? "revoked" : "not_a_manager";

await prisma.rolePermission.upsert({
  where: { roleId_permissionId: { roleId: r.id, permissionId: p.id } },
  update: {}, // nothing to change - link exists or doesn't
  create: { roleId: r.id, permissionId: p.id },
});

const activeManagerCount = await prisma.userRole.count({
  where: {
    revokedAt: null,
    role: { name: Roles.MANAGER },
    user: { isActive: true },
  },
});
if (activeManagerCount > 0) { /* skip - runtime owns the list */ }
else { /* seed from MANAGER_CHAT_IDS */ }

